export const DAEGU_BLOCKS: DaeguBlock[] = DAEGU_BLOCK_DEFINITIONS.map(createDaeguBlock);

export const DAEGU_SEATMAP_VIEWPORT: DaeguSeatMapViewport = {
  x: 0,
  y: 0,
  width: DAEGU_SEATMAP_IMAGE.imageWidth,
  height: DAEGU_SEATMAP_IMAGE.imageHeight,
  padding: 0,
};

const SIDE_LABELS: Record<DaeguSide, string> = {
  FIRST_BASE: '1루',
  THIRD_BASE: '3루',
  CENTER: '중앙',
  OUTFIELD: '외야',
};

const FAN_ROLE_LABELS: Record<DaeguFanRole, string> = {
  HOME: '홈',
  AWAY: '원정',
  NEUTRAL: '중립',
};

const SOURCE_LABELS: Record<DaeguSourceConfidence, string> = {
  OFFICIAL: '공식 확인',
  UNVERIFIED: '수동 확인 필요',
};

const TRACE_STATUS_LABELS: Record<DaeguTraceStatus, string> = {
  OFFICIAL_IMAGE_TRACED: '공식 이미지 트레이싱 완료',
  NEEDS_OPERATOR_REVIEW: '운영자 좌표 검수 필요',
};

const TRACE_METHOD_LABELS: Record<DaeguTraceMethod, string> = {
  PATH_TRACED_FROM_OFFICIAL_IMAGE: '공식 PNG 직접 트레이싱',
  LEGACY_SCALED_POLYGON: '기존 좌표계 변환 polygon',
  PIXEL_COMPONENT_CANDIDATE: '공식 PNG 픽셀 후보',
  TODO_UNMEASURED: '직접 측정 전 TODO',
};

export function getDaeguSideLabel(side: DaeguSide) {
  return SIDE_LABELS[side];
}

export function getDaeguFanRoleLabel(fanRole: DaeguFanRole) {
  return FAN_ROLE_LABELS[fanRole];
}

export function getDaeguSourceLabel(sourceConfidence: DaeguSourceConfidence) {
  return SOURCE_LABELS[sourceConfidence];
}

export function getDaeguTraceStatusLabel(traceStatus: DaeguTraceStatus) {
  return TRACE_STATUS_LABELS[traceStatus];
}

export function getDaeguTraceMethodLabel(traceMethod: DaeguTraceMethod) {
  return TRACE_METHOD_LABELS[traceMethod];
}
